,p_search_type=>'SIMPLE'
,p_location=>'LOCAL'
,p_query_type=>'SQL'
,p_query_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    r.req_id,',
'    j.title,',
'    r.status,',
'    d.name AS department_name,',
'    j.title AS result_title,',
'    ''Status: '' || r.status ||',
'        CASE',
'            WHEN d.name IS NOT NULL THEN '' - '' || d.name',
'        END AS result_description',
'FROM tms_job_requisitions r',
'JOIN tms_jobs j',
'    ON j.job_id = r.job_id',
'LEFT JOIN tms_departments d',
'    ON d.dept_id = r.dept_id'))
,p_searchable_columns=>'TITLE:STATUS:DEPARTMENT_NAME:RESULT_TITLE:RESULT_DESCRIPTION'
,p_pk_column_name=>'REQ_ID'
