 p_id=>wwv_flow_imp.id(4483277683493032635)
,p_plug_name=>'Applied'
,p_static_id=>'applied'
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2076152157930740558
,p_plug_display_sequence=>30
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ',
'  c.candidate_id, ',
'  c.req_id, ',
'  c.first_name || '' '' || c.last_name as candidate_name, ',
'  d.name as department_name, ',
'  c.current_stage, ',
'  ''Applied: '' || to_char(c.applied_date, ''DD-Mon-YYYY'') as applied_on ',
'from ',
'  tms_candidates c ',
'  left join tms_job_requisitions r on c.req_id = r.req_id ',
'  left join tms_departments d on r.dept_id = d.dept_id ',
'where ',
'  (',
'    :P4_REQ_ID is null ',
'    or c.req_id = :P4_REQ_ID',
'  ) ',
'  and (',
'    :P4_STAGE is null ',
'    or c.current_stage = :P4_STAGE',
'  ) ',
'order by ',
'  c.applied_date desc;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_ajax_items_to_submit=>'P4_REQ_ID'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
);
